solution:
k = int(input())
words = input().split()
counts = {}
for w in words:
    counts[w] = counts.get(w, 0) + 1

ranking = sorted(counts.items(), key=lambda p: (-p[1], p[0]))
for word, cnt in ranking[:k]:
    print(word, cnt)
